<script setup>
import { ref, computed, watch } from 'vue'
import { ElMessage, ElMessageBox, ElNotification } from 'element-plus'
import MainLayout from '@/layouts/full/MainLayout.vue'
import { supabase } from '@/services/supabase.js'
import { useAuthStore } from '@/stores/auth'
const authStore = useAuthStore()
const merchantId = computed(() => authStore.merchant?.id)
const records = ref([]), parties = ref({ agents: [], customers: [] })
const loading = ref(false), saving = ref(false), search = ref(''), direction = ref(''), status = ref('')
const expanded = ref([]), dialog = ref(false), paymentDialog = ref(false), editing = ref(null), selected = ref(null)
const form = ref({}), payment = ref({}), referenceType = ref('other')
const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Lagos', year:'numeric',month:'2-digit',day:'2-digit' }).format(new Date())
const money = n => new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN'}).format(Number(n || 0))
const date = d => d ? new Date(d.length === 10 ? d+'T00:00:00' : d).toLocaleDateString('en-NG',{day:'2-digit',month:'short',year:'numeric'}) : '—'
async function rpc(name,args={}) { const {data,error}=await supabase.rpc(name,{p_merchant_id:merchantId.value,...args}); if(error) throw error; return data }
let generation=0
async function load(){ const g=++generation; loading.value=true; try { const [r,p]=await Promise.all([rpc('cd_list'),rpc('cd_parties')]); if(g===generation){records.value=r;parties.value=p} } catch(e){if(g===generation) ElMessage.error(e.message)} finally{if(g===generation) loading.value=false} }
watch(merchantId, id=>{records.value=[]; parties.value={agents:[],customers:[]}; expanded.value=[];dialog.value=false;paymentDialog.value=false;if(id)load();else{generation++;loading.value=false}}, {immediate:true})
const filtered=computed(()=>records.value.filter(r=>(!direction.value||r.direction===direction.value)&&(!status.value||r.status===status.value)&&[r.party_name,r.notes].some(v=>String(v||'').toLowerCase().includes(search.value.toLowerCase()))))
const sum=d=>records.value.filter(r=>r.direction===d&&r.status!=='closed').reduce((s,r)=>s+Number(r.balance),0)
const stats=computed(()=>[{label:'Outstanding receivables',value:money(sum('credit')),icon:'fa-arrow-down',tone:'green'},{label:'Outstanding payables',value:money(sum('debit')),icon:'fa-arrow-up',tone:'red'},{label:'Net outstanding',value:money(sum('credit')-sum('debit')),icon:'fa-wallet',tone:'blue'},{label:'Overdue records',value:records.value.filter(r=>r.status==='overdue').length,icon:'fa-clock',tone:'amber'}])
const options=computed(()=>referenceType.value==='agent'?parties.value.agents:parties.value.customers)
function openRecord(r=null){editing.value=r?.id||null;referenceType.value=r?.agent_id?'agent':r?.customer_id?'customer':'other';form.value=r?{...r,amount:Number(r.amount),reference_id:r.agent_id||r.customer_id}:{direction:'credit',party_name:'',amount:null,transaction_date:today(),due_date:null,notes:'',reference_id:null};dialog.value=true}
function changeReference(){form.value.reference_id=null}
function chooseParty(id){const p=options.value.find(x=>x.id===id);if(p)form.value.party_name=p.name}
async function mutate(action,id,data={}){if(saving.value)return false;saving.value=true;try{await rpc('cd_mutate',{p_action:action,p_record_id:id,p_data:data});ElNotification({title:'Success',message:'Record saved successfully',type:'success'});await load();return true}catch(e){ElMessage.error(e.message);return false}finally{saving.value=false}}
async function saveRecord(){const f=form.value;if(!f.party_name?.trim()||!(f.amount>0)||!f.transaction_date||(referenceType.value!=='other'&&!f.reference_id))return ElMessage.warning('Complete all required fields');if(await mutate(editing.value?'edit':'create',editing.value,{direction:f.direction,party_name:f.party_name,amount:f.amount,transaction_date:f.transaction_date,due_date:f.due_date||null,notes:f.notes,agent_id:referenceType.value==='agent'?f.reference_id:null,customer_id:referenceType.value==='customer'?f.reference_id:null}))dialog.value=false}
function openPayment(r,p=null){selected.value=r;payment.value=p?{...p,amount:Number(p.amount)}:{amount:null,payment_date:today(),method:'transfer',notes:''};paymentDialog.value=true}
const maxPayment=computed(()=>Number(selected.value?.balance||0)+Number(selected.value?.payments.find(p=>p.id===payment.value.id)?.amount||0))
async function savePayment(){const p=payment.value;if(!(p.amount>0)||p.amount>maxPayment.value||!p.payment_date)return ElMessage.warning('Enter a valid amount and payment date');if(await mutate(p.id?'payment_edit':'payment_add',selected.value.id,p))paymentDialog.value=false}
async function confirmAction(action,r,p=null){try{await ElMessageBox.confirm(action==='delete'?'Remove this record and its payments from the register? Audit history is retained.':action==='payment_delete'?'Remove this payment and recalculate the balance?':action==='close'?'Close this fully settled record?':'Reopen this record?', 'Confirm action',{type:'warning',confirmButtonText:'Confirm'})}catch{return}await mutate(action,r.id,p?{id:p.id}:{})}
const statusType=s=>({closed:'info',settled:'success',partial:'warning',overdue:'danger',open:'primary'}[s])
</script>
<template>
<MainLayout><div class="facilities-page" v-loading="loading">
  <div class="page-header"><div class="header-left"><div class="header-icon"><i class="fa-solid fa-arrow-right-arrow-left"/></div><div><h1 class="page-title">Credit &amp; Debit</h1><p class="page-subtitle">Manage receivables, payables and payment history</p></div></div><button class="add-btn" :disabled="!merchantId||saving" @click="openRecord()"><i class="fa-solid fa-plus"/> New Record</button></div>
  <div class="stats-row"><div v-for="s in stats" :key="s.label" class="stat-card"><div class="stat-icon" :class="s.tone"><i class="fa-solid" :class="s.icon"/></div><div><div class="stat-value">{{s.value}}</div><div class="page-subtitle">{{s.label}}</div></div></div></div>
  <div class="table-container"><div class="filters"><el-input v-model="search" placeholder="Search name or notes" clearable/><el-select v-model="direction" placeholder="All types" clearable><el-option label="Credit · They owe us" value="credit"/><el-option label="Debit · We owe them" value="debit"/></el-select><el-select v-model="status" placeholder="All statuses" clearable><el-option v-for="s in ['open','partial','overdue','settled','closed']" :key="s" :label="s" :value="s"/></el-select><el-button @click="load" :disabled="!merchantId">Refresh</el-button></div>
  <el-table :data="filtered" row-key="id" :expand-row-keys="expanded" @expand-change="(_,rows)=>expanded=rows.map(r=>r.id)" empty-text="No credit or debit records" style="width:100%">
    <el-table-column type="expand"><template #default="{row:r}"><div class="history"><div class="history-head"><div><strong>Payment history · {{r.party_name}}</strong><p class="page-subtitle">{{r.notes||'No notes'}} · Created {{date(r.created_at)}} · Updated {{date(r.updated_at)}} <span v-if="r.closed_at"> · Closed {{date(r.closed_at)}}</span></p></div><el-button v-if="!r.closed_at && Number(r.balance)>0" type="primary" :disabled="saving" @click="openPayment(r)">+ Record payment</el-button></div>
      <el-table :data="r.payments" empty-text="No payments recorded"><el-table-column label="Payment date" min-width="120"><template #default="{row:p}">{{date(p.payment_date)}}</template></el-table-column><el-table-column label="Amount" min-width="120"><template #default="{row:p}">{{money(p.amount)}}</template></el-table-column><el-table-column prop="method" label="Method"/><el-table-column prop="notes" label="Notes"/><el-table-column label="Recorded at" min-width="120"><template #default="{row:p}">{{date(p.created_at)}}</template></el-table-column><el-table-column label="Actions" width="110"><template #default="{row:p}"><div v-if="!r.closed_at" class="actions"><button title="Edit payment" :disabled="saving" @click="openPayment(r,p)"><i class="fa-solid fa-pen"/></button><button class="danger" title="Delete payment" :disabled="saving" @click="confirmAction('payment_delete',r,p)"><i class="fa-solid fa-trash"/></button></div></template></el-table-column></el-table><p class="total">Total paid: {{money(r.paid)}} · Outstanding: {{money(r.balance)}}</p></div></template></el-table-column>
    <el-table-column label="Party" min-width="160"><template #default="{row:r}"><strong>{{r.party_name}}</strong><div class="page-subtitle">{{r.agent_id?'Agent':r.customer_id?'Customer':'Other'}}</div></template></el-table-column>
    <el-table-column label="Type" width="100"><template #default="{row:r}"><el-tag :type="r.direction==='credit'?'success':'danger'" effect="light">{{r.direction}}</el-tag></template></el-table-column>
    <el-table-column v-for="c in [{key:'amount',label:'Amount'},{key:'paid',label:'Paid'},{key:'balance',label:'Balance'}]" :key="c.key" :label="c.label" min-width="125"><template #default="{row:r}"><strong>{{money(r[c.key])}}</strong></template></el-table-column>
    <el-table-column label="Date" min-width="110"><template #default="{row:r}">{{date(r.transaction_date)}}</template></el-table-column><el-table-column label="Due date" min-width="110"><template #default="{row:r}">{{date(r.due_date)}}</template></el-table-column>
    <el-table-column label="Status" width="105"><template #default="{row:r}"><el-tag :type="statusType(r.status)">{{r.status}}</el-tag></template></el-table-column>
    <el-table-column label="Actions" width="160"><template #default="{row:r}"><div class="actions"><button v-if="!r.closed_at && Number(r.balance)>0" title="Record payment" :disabled="saving" @click="openPayment(r)"><i class="fa-solid fa-money-bill-wave"/></button><button v-if="!r.closed_at" title="Edit" :disabled="saving" @click="openRecord(r)"><i class="fa-solid fa-pen"/></button><button v-if="r.closed_at || Number(r.balance)===0" :title="r.closed_at?'Reopen':'Close'" :disabled="saving" @click="confirmAction(r.closed_at?'reopen':'close',r)"><i class="fa-solid" :class="r.closed_at?'fa-lock-open':'fa-lock'"/></button><button class="danger" title="Delete" :disabled="saving" @click="confirmAction('delete',r)"><i class="fa-solid fa-trash"/></button></div></template></el-table-column>
  </el-table></div>
  <el-dialog v-model="dialog" :title="editing?'Edit record':'New credit or debit record'" width="min(680px, 94vw)" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving" destroy-on-close><el-form label-position="top" :disabled="saving"><div class="form-grid"><el-form-item label="Transaction type" required><el-select v-model="form.direction"><el-option label="Credit — They owe us" value="credit"/><el-option label="Debit — We owe them" value="debit"/></el-select></el-form-item><el-form-item label="Reference type"><el-select v-model="referenceType" @change="changeReference"><el-option label="Other / manual entry" value="other"/><el-option label="Agent" value="agent"/><el-option label="Customer" value="customer"/></el-select></el-form-item><el-form-item v-if="referenceType!=='other'" label="Select reference" required><el-select v-model="form.reference_id" filterable @change="chooseParty"><el-option v-for="p in options" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="Party name" required><el-input v-model="form.party_name"/></el-form-item><el-form-item label="Amount (NGN)" required><el-input-number v-model="form.amount" :min="0.01" :precision="2" :controls="false"/></el-form-item><el-form-item label="Transaction date" required><el-date-picker v-model="form.transaction_date" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="Due date (optional)"><el-date-picker v-model="form.due_date" type="date" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="Description / notes"><el-input v-model="form.notes" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="dialog=false">Cancel</el-button><el-button type="primary" :loading="saving" @click="saveRecord">Save record</el-button></template></el-dialog>
  <el-dialog v-model="paymentDialog" :title="payment.id?'Edit payment':'Record payment'" width="min(520px, 94vw)" :close-on-click-modal="false" :show-close="!saving" :close-on-press-escape="!saving" destroy-on-close><div class="payment-summary">{{selected?.party_name}} · Maximum payment: <strong>{{money(maxPayment)}}</strong></div><el-form label-position="top" :disabled="saving"><el-form-item label="Amount (NGN)" required><el-input-number v-model="payment.amount" :min="0.01" :max="maxPayment" :precision="2" :controls="false"/></el-form-item><el-form-item label="Payment date" required><el-date-picker v-model="payment.payment_date" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="Payment method"><el-select v-model="payment.method"><el-option v-for="m in ['transfer','cash','cheque','other']" :key="m" :label="m" :value="m"/></el-select></el-form-item><el-form-item label="Notes / reference"><el-input v-model="payment.notes" type="textarea"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="paymentDialog=false">Cancel</el-button><el-button type="primary" :loading="saving" @click="savePayment">Save payment</el-button></template></el-dialog>
</div></MainLayout>
</template>
<style scoped>
.facilities-page{padding:24px;min-height:100vh;background:#f5f7f9;color:#1a2332;--el-color-primary:#1a9e85;font-family:'DM Sans',sans-serif}.page-header,.stat-card,.table-container{background:white;border-radius:14px;box-shadow:0 1px 4px #0000000f}.page-header{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;margin-bottom:20px;gap:12px}.header-left,.stat-card,.history-head{display:flex;align-items:center;gap:14px}.header-icon,.stat-icon{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;flex-shrink:0}.header-icon,.add-btn{background:linear-gradient(135deg,#27bfa0,#1a9e85);color:white}.page-title{font-size:20px;font-weight:700;margin:0}.page-subtitle{font-size:13px;color:#7a8899;margin:4px 0}.add-btn{border:0;border-radius:10px;padding:11px 20px;font-weight:600;cursor:pointer;white-space:nowrap}.stats-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:20px}.stat-card{padding:18px}.stat-value{font-size:19px;font-weight:700;overflow-wrap:anywhere}.green{background:#e2f6ef;color:#159b82}.red{background:#feecec;color:#dc5656}.blue{background:#eaf2ff;color:#397acb}.amber{background:#fff4da;color:#b77908}.table-container{overflow:hidden}.filters{display:flex;gap:12px;padding:18px;flex-wrap:wrap}.filters>*{flex:1;min-width:140px}.filters>.el-button{flex:0}.actions{display:flex;gap:6px}.actions button{border:0;background:#e8f5f2;color:#168a75;border-radius:7px;width:30px;height:30px;cursor:pointer}.actions .danger{background:#feecec;color:#d54b4b}button:disabled{opacity:.5;cursor:not-allowed}.history{padding:20px 28px;background:#f5f8fa}.history-head{justify-content:space-between;margin-bottom:16px}.total{text-align:right;font-weight:600;margin-top:16px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.el-form :deep(.el-select),.el-form :deep(.el-input-number),.el-form :deep(.el-date-editor){width:100%}.payment-summary{background:#eaf7f4;padding:14px;border-radius:10px;margin-bottom:16px}:deep(.el-dialog){border-radius:18px;padding:24px;--el-color-primary:#1a9e85}:deep(.el-dialog__title){font-weight:700}:deep(.el-table th.el-table__cell){background:#f7f9fb;color:#64748b;text-transform:uppercase;font-size:11px}:deep(.el-tag){text-transform:capitalize}@media(max-width:1000px){.stats-row{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.facilities-page{padding:12px}.stats-row,.form-grid{grid-template-columns:1fr}.page-header,.history-head{align-items:flex-start;flex-direction:column}.history{padding:12px}}
</style>
